import docx, os

def dump_all(dirpath):
    for f in sorted(os.listdir(dirpath)):
        if f.endswith('.docx'):
            p = os.path.join(dirpath, f)
            out_p = f'/tmp/{f}.txt'
            doc = docx.Document(p)
            with open(out_p, 'w') as out:
                out.write(f'=== {f} ===\n')
                for para in doc.paragraphs:
                    if para.text.strip():
                        out.write(para.text + '\n')
                for t in doc.tables:
                    out.write('--- TABLE ---\n')
                    for r in t.rows:
                        out.write(' | '.join(c.text.strip().replace('\n', ' ') for c in r.cells) + '\n')
            print(f'Wrote {out_p}')

dump_all('specs')
dump_all('site')
dump_all('correspondence')
"

